function imageSlot(key, alt) { return `<img data-asset="${esc(key)}" alt="${esc(alt)}" class="lesson-image" src="data:image/gif;base64,R0lGODlhAQABAAAAACw="/>`; }
function stageButton(stage, label, current) { return `<button class="lesson-step ${stage === current ? 'active' : ''}" data-stage="${stage}">${esc(label)}</button>`; }
