    app.innerHTML = page('learn', `<div class="lesson-topbar"><button class="crumb" data-go="course/${level}">← ${esc(course.meta?.title || `MOTIVA ${level}`)}</button><div>${prev}${next}</div></div><section class="lesson-hero"><div><p class="eyebrow">MOTIVA ${level} · Interactive book · Unit ${String(unit).padStart(2, '0')}</p><h1>${esc(u.titleFr)}</h1><p class="lead">${esc(u.titleEn || '')}</p><div class="lesson-goal">Cards, listening, active practice, correction and account-saved progress.</div></div>${imageSlot(`courses/${level}/images/${imageName}`, u.theme || u.titleFr)}</section><nav class="lesson-steps" aria-label="Interactive book stages">${stageButton('discover', '1 Discover', stage)}${stageButton('listen', '2 Listen', stage)}${stageButton('use', '3 Use', stage)}${stageButton('checkpoint', '4 Check', stage)}${stageButton('review', '5 Review', stage)}</nav>${lessonStageContent(stage, u, level, unit)}<section class="section"><div class="section-heading"><div><p class="eyebrow">Book contents</p><h2>${esc(course.meta?.title || `MOTIVA ${level}`)}</h2></div><p>Choose another unit without leaving the interactive book.</p></div><div class="unit-list">${chapters}</div></section>`);
