async function openReference(key, title) {
  try { const url = await protectedBlob(key); const old = document.getElementById('reference-reader'); if (old) old.remove(); const dialog = document.createElement('dialog'); dialog.id = 'reference-reader'; dialog.className = 'reference-reader'; dialog.innerHTML = `<div class="reader-top"><div><p class="eyebrow">Protected reference</p><h2>${esc(title || 'Reference')}</h2></div><button class="button alt" data-close-reader>Close</button></div><iframe title="${esc(title || 'Protected reference')}" src="${url}"></iframe>`; document.body.append(dialog); dialog.showModal(); } catch { setNotice('The protected reference could not be opened. Please check your active membership.', 'error'); render(); }
}
async function playProtected(key, button) { const url = await protectedBlob(key); if (state.activeAudio?.src === url && !state.activeAudio.paused) { state.activeAudio.pause(); button.classList.remove('playing'); button.querySelector('.audio-icon').textContent = '▶'; return; } if (state.activeAudio) state.activeAudio.pause(); document.querySelectorAll('.audio-control.playing').forEach((node) => { node.classList.remove('playing'); const icon = node.querySelector('.audio-icon'); if (icon) icon.textContent = '▶'; }); const audio = new Audio(url); state.activeAudio = audio; button.classList.add('playing'); button.querySelector('.audio-icon').textContent = '❚❚'; audio.onended = () => { button.classList.remove('playing'); button.querySelector('.audio-icon').textContent = '▶'; }; await audio.play(); }
function updateBuilder(id) { const builder = state.builders.get(id); const output = document.getElementById(`builder-output-${id}`); if (!builder || !output) return; output.innerHTML = builder.selected.length ? esc(sentenceFrom(builder.selected.map((index) => builder.tokens[index]))) : '<span>Tap words to build your sentence.</span>'; document.querySelectorAll(`[data-builder="${CSS.escape(id)}"][data-token]`).forEach((button) => { button.disabled = builder.selected.includes(Number(button.dataset.token)); }); }
function feedback(box, ok, message) { const out = box.querySelector('.feedback'); if (!out) return; out.textContent = message; out.className = `feedback ${ok ? 'ok' : 'no'}`; }
function activeLessonFromBox(box) { return { level: String(box.dataset.level || ''), unit: String(box.dataset.unit || ''), exercise: String(box.dataset.exercise || '') }; }
async function submitAttempt(box, response, messages) {
  if (box.dataset.submitting === 'true') return false;
  box.dataset.submitting = 'true';
  const controls = [...box.querySelectorAll('[data-check-mcq], [data-check-fill], [data-check-match], [data-check-order], [data-check-dictation]')];
  controls.forEach((control) => { control.disabled = true; });
  const item = activeLessonFromBox(box);
  try {
    const outcome = await saveAttempt(item.level, item.unit, item.exercise, response);
    const ok = Boolean(outcome.correct);
    feedback(box, ok, ok ? messages.correct : messages.incorrect);
    return ok;
  } catch {
    feedback(box, false, 'Your answer could not be saved. Check your connection and try again.');
    return false;
  } finally {
    delete box.dataset.submitting;
    controls.forEach((control) => { control.disabled = false; });
  }
}

async function handleClick(event) {
  const target = event.target.closest('[data-go]'); if (target) { go(target.dataset.go); return; }
  const share = event.target.closest('[data-share]'); if (share && state.placement.result) { const result = state.placement.result; const url = placementShareUrl(result); const text = placementShareText(result); const links = { whatsapp: `https://wa.me/?text=${encodeURIComponent(`${text} ${url}`)}`, facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`, x: `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}` }; try { if (share.dataset.share === 'native' && navigator.share) await navigator.share({ title: 'My MOTIVA placement result', text, url }); else if (share.dataset.share === 'copy') { await navigator.clipboard.writeText(`${text} ${url}`); setNotice('Placement result link copied.'); renderPlacement(); } else if (links[share.dataset.share]) window.open(links[share.dataset.share], '_blank', 'noopener,noreferrer'); else if (share.dataset.share === 'native') { await navigator.clipboard.writeText(`${text} ${url}`); setNotice('Placement result link copied.'); renderPlacement(); } } catch (error) { if (error.name !== 'AbortError') { setNotice('The share link could not be created.'); renderPlacement(); } } return; }
  const placementChoice = event.target.closest('[data-placement-choice]'); if (placementChoice) { state.placement.answers[state.placement.index] = Number(placementChoice.dataset.placementChoice); renderPlacement(); return; }
  const placementRestart = event.target.closest('[data-placement-restart]'); if (placementRestart) { state.placement = { answers: [], index: 0, result: null }; localStorage.removeItem('motiva-placement-result-v1'); renderPlacement(); return; }
  const placementNav = event.target.closest('[data-placement-nav]'); if (placementNav && !placementNav.disabled) { if (placementNav.dataset.placementNav === 'prev') state.placement.index = Math.max(0, state.placement.index - 1); else if (state.placement.index === PLACEMENT_QUESTIONS.length - 1) { state.placement.result = placementResult(); localStorage.setItem('motiva-placement-result-v1', JSON.stringify(state.placement.result)); } else state.placement.index += 1; renderPlacement(); return; }
  const closeReader = event.target.closest('[data-close-reader]'); if (closeReader) { closeReader.closest('dialog')?.close(); closeReader.closest('dialog')?.remove(); return; }
  const audio = event.target.closest('[data-audio]'); if (audio) { try { await playProtected(audio.dataset.audio, audio); } catch { setNotice('Audio could not be loaded. Check your active membership.', 'error'); render(); } return; }
  const reference = event.target.closest('[data-reference]'); if (reference) { await openReference(reference.dataset.reference, reference.dataset.referenceTitle); return; }
  const stage = event.target.closest('[data-stage]'); if (stage) { const bits = route().split('/'); const surface = bits[0] === 'book' ? 'book' : 'lesson'; go(`${surface}/${bits[1]}/${bits[2]}/${stage.dataset.stage}`); return; }
  const nextStage = event.target.closest('[data-stage-next]'); if (nextStage) { const bits = route().split('/'); const surface = bits[0] === 'book' ? 'book' : 'lesson'; const order = ['discover', 'listen', 'use', 'checkpoint', 'review']; const current = bits[3] || 'discover'; const next = nextStage.dataset.stageNext || order[Math.min(order.indexOf(current) + 1, order.length - 1)]; go(`${surface}/${bits[1]}/${bits[2]}/${next}`); return; }
  const flip = event.target.closest('[data-flip-card]'); if (flip) { flip.classList.toggle('flipped'); return; }
  const mcq = event.target.closest('[data-check-mcq]'); if (mcq) { const box = mcq.closest('.exercise-card'); const picked = box.querySelector('input:checked'); if (!picked) { feedback(box, false, 'Choose an answer first.'); return; } await submitAttempt(box, picked.value, { correct: 'Correct — keep this pattern.', incorrect: 'Not quite. Review the correction, then try again.' }); return; }
  const fill = event.target.closest('[data-check-fill]'); if (fill) { const box = fill.closest('.exercise-card'); const input = box.querySelector('input'); await submitAttempt(box, input.value, { correct: 'Correct — excellent retrieval.', incorrect: 'Check the correction and say the full phrase once.' }); return; }
  const match = event.target.closest('[data-check-match]'); if (match) { const box = match.closest('.exercise-card'); const selections = [...box.querySelectorAll('select[data-match-answer]')]; if (!selections.length || selections.some((select) => !select.value)) { feedback(box, false, 'Choose a meaning for every item first.'); return; } await submitAttempt(box, selections.map((select) => select.value), { correct: 'All matches are correct.', incorrect: 'Some matches need another look.' }); return; }
  const token = event.target.closest('[data-token][data-builder]'); if (token) { const builder = state.builders.get(token.dataset.builder); if (builder && !builder.selected.includes(Number(token.dataset.token))) { builder.selected.push(Number(token.dataset.token)); updateBuilder(token.dataset.builder); } return; }
  const reset = event.target.closest('[data-reset-builder]'); if (reset) { const builder = state.builders.get(reset.dataset.resetBuilder); if (builder) { builder.selected = []; updateBuilder(reset.dataset.resetBuilder); } return; }
  const order = event.target.closest('[data-check-order]'); if (order) { const box = order.closest('.exercise-card'); const builder = state.builders.get(order.dataset.builder); const response = sentenceFrom((builder?.selected || []).map((index) => builder.tokens[index])); if (!response) { feedback(box, false, 'Build the sentence first.'); return; } await submitAttempt(box, response, { correct: 'Correct word order — read it aloud once.', incorrect: 'Try a different order, then check again.' }); return; }
  const dictation = event.target.closest('[data-check-dictation]'); if (dictation) { const box = dictation.closest('.exercise-card'); const input = box.querySelector('textarea'); if (!input.value.trim()) { feedback(box, false, 'Write what you hear first.'); return; } await submitAttempt(box, input.value, { correct: 'Excellent listening and writing.', incorrect: 'Compare your version with the transcript, then replay once.' }); return; }
  const complete = event.target.closest('[data-complete-lesson]'); if (complete) { const bits = route().split('/'); complete.disabled = true; try { await markComplete(bits[1], Number(bits[2])); setNotice('Lesson complete. Your next step is ready.'); const surface = bits[0] === 'book' ? 'book' : 'lesson'; go(Number(bits[2]) < 12 ? `${surface}/${bits[1]}/${Number(bits[2]) + 1}` : 'progress'); } catch { complete.disabled = false; setNotice('Your lesson could not be completed. Check your connection and try again.', 'error'); render(); } return; }
  if (event.target.id === 'signup') { const form = document.getElementById('login-form'); try { await supabase('/auth/v1/signup', { method: 'POST', body: { email: form.email.value, password: form.password.value, options: { emailRedirectTo: location.href.split('#')[0] } } }); setNotice('Account created. Confirm your email if required, then sign in.'); renderLogin(); } catch (e) { setNotice(e.message, 'error'); renderLogin(); } return; }
  if (event.target.id === 'logout') { saveSession(null); state.me = null; loadProgress(); setNotice('Signed out.'); go('today'); return; }
  const toggle = event.target.closest('.toggle-promo'); if (toggle) { try { await api(`/api/admin/promos/${toggle.dataset.id}`, { method: 'PATCH', body: { active: toggle.dataset.active !== '1' } }); setNotice('Discount code status updated.'); await renderAdmin('admin/coupons'); } catch (e) { setNotice(e.message, 'error'); await renderAdmin('admin/coupons'); } return; }
  const pick = event.target.closest('.pick-user'); if (pick) { const form = document.getElementById('manual-subscription-form'); form.userId.value = pick.dataset.id; form.email.value = pick.dataset.email; form.endsAt.focus(); return; }
  const extend = event.target.closest('.extend-subscription'); if (extend) { const form = document.getElementById('manual-subscription-form'); form.userId.value = extend.dataset.user; const row = (state.admin?.subscriptions || []).find((item) => item.user_id === extend.dataset.user); form.email.value = row?.profiles?.email || extend.dataset.user; form.startsAt.value = extend.dataset.start ? new Date(extend.dataset.start).toISOString().slice(0, 16) : new Date().toISOString().slice(0, 16); form.endsAt.value = extend.dataset.end ? new Date(extend.dataset.end).toISOString().slice(0, 16) : ''; form.endsAt.focus(); return; }
  const cancel = event.target.closest('.cancel-subscription'); if (cancel) { if (!confirm('Cancel this manual subscription now? The learner will lose access immediately.')) return; try { await api(`/api/admin/subscriptions/${cancel.dataset.user}/cancel`, { method: 'POST' }); setNotice('Manual subscription cancelled.'); await renderAdmin('admin/people'); } catch (e) { setNotice(e.message, 'error'); await renderAdmin('admin/people'); } }
}
async function handleSubmit(event) {
  const form = event.target; event.preventDefault();
  if (form.id === 'login-form') { try { const data = await supabase('/auth/v1/token?grant_type=password', { method: 'POST', body: { email: form.email.value, password: form.password.value } }); saveSession(data); await getMe(); setNotice('Signed in successfully.'); go('today'); } catch (e) { setNotice(e.message, 'error'); renderLogin(); } return; }
  if (form.id === 'checkout-form') { try { const data = await api('/api/checkout', { method: 'POST', body: { code: form.code.value.trim() || undefined } }); if (data.freeAccess) { await getMe(); setNotice(`Free access activated until ${new Date(data.activeUntil).toLocaleString()}.`); go('today'); } else { const discount = data.discountPercent ? ` Your code ${data.code} provides ${data.discountPercent}% off; mention it when contacting the owner.` : ''; setNotice(`Manual payment information refreshed.${discount}`); state.plan = { ...state.plan, ...data }; renderMembership(); } } catch (e) { setNotice(e.message.replaceAll('_', ' '), 'error'); renderMembership(); } return; }
  if (form.id === 'plan-form') { try { await api('/api/admin/plan', { method: 'POST', body: { priceCents: Number(form.priceCents.value), currency: form.currency.value.trim().toUpperCase() } }); setNotice('Monthly manual-payment price saved.'); await getPlan(); await renderAdmin('admin/coupons'); } catch (e) { setNotice(e.message, 'error'); await renderAdmin('admin/coupons'); } return; }
  if (form.id === 'payment-settings-form') { try { await api('/api/admin/payment-settings', { method: 'POST', body: { instructions: form.instructions.value, contactLabel: form.contactLabel.value, contactUrl: form.contactUrl.value } }); setNotice('Payment instructions and contact method saved.'); await getPlan(); await renderAdmin('admin/coupons'); } catch (e) { setNotice(e.message, 'error'); await renderAdmin('admin/coupons'); } return; }
  if (form.id === 'user-search-form') { try { const data = await api(`/api/admin/users?query=${encodeURIComponent(form.query.value)}`); state.users = data.users || []; setNotice(`${state.users.length} matching learner(s) found.`); await renderAdmin('admin/people'); } catch (e) { setNotice(e.message, 'error'); await renderAdmin('admin/people'); } return; }
  if (form.id === 'manual-subscription-form') { try { await api('/api/admin/manual-subscriptions', { method: 'POST', body: { userId: form.userId.value, startsAt: new Date(form.startsAt.value).toISOString(), endsAt: new Date(form.endsAt.value).toISOString() } }); setNotice('Manual subscription saved.'); await renderAdmin('admin/people'); } catch (e) { setNotice(e.message, 'error'); await renderAdmin('admin/people'); } return; }
  if (form.id === 'promo-form') { try { const data = Object.fromEntries(new FormData(form)); await api('/api/admin/promos', { method: 'POST', body: { ...data, percentOff: Number(data.percentOff), freeDurationDays: data.freeDurationDays ? Number(data.freeDurationDays) : 0, maxRedemptions: data.maxRedemptions || undefined, validUntil: data.validUntil || undefined } }); setNotice('Discount code created.'); await renderAdmin('admin/coupons'); } catch (e) { setNotice(e.message, 'error'); await renderAdmin('admin/coupons'); } }
}
function renderLogin() { app.innerHTML = page('', `<section class="login-layout"><div><p class="eyebrow">Secure learner account</p><h1>Welcome to your French learning space.</h1><p class="lead">Sign in to continue lessons, save account progress across devices and access your membership.</p><div class="login-points"><span>✦ Continue where you stopped</span><span>◉ Practice with instant correction</span><span>♬ Protected listening inside lessons</span></div></div><section class="login-card"><h2>Sign in or create an account</h2><form id="login-form"><div class="field"><label>Email</label><input name="email" type="email" autocomplete="email" required></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="current-password" minlength="8" required></div><div class="buttons"><button class="button" type="submit">Sign in</button><button class="button alt" type="button" id="signup">Create account</button></div></form><p class="muted">New accounts may require email confirmation depending on the owner’s Supabase settings.</p></section></section>`); }
async function render() {
  const parts = route().split('/'); const main = parts[0];
  if (main === 'login') return renderLogin();
  if (main === 'today' || main === 'home') return renderToday();
  if (main === 'learn') return parts[1] && LEVELS.includes(parts[1]) ? renderCourse(parts[1]) : renderLearn();
  if (main === 'placement') return renderPlacement();
  if (main === 'course' && LEVELS.includes(parts[1])) return renderCourse(parts[1]);
  if (main === 'lesson' && LEVELS.includes(parts[1]) && parts[2]) return renderLesson(parts[1], parts[2], parts[3]);
  if (main === 'book' && LEVELS.includes(parts[1]) && parts[2]) return renderLesson(parts[1], parts[2], parts[3]);
  if (main === 'practice') { if (parts[1] === 'tcf') return renderTcf(parts[2]); if (parts[1] === 'grammar') return renderGrammar(parts[2]); return renderPractice(); }
  if (main === 'progress') return renderProgress();
  if (main === 'membership' || main === 'account') return renderMembership();
  if (main === 'admin') return renderAdmin(parts[1] ? `admin/${parts[1]}` : 'admin');
  return renderToday();
}
async function boot() { try { const savedPlacement = JSON.parse(localStorage.getItem('motiva-placement-result-v1') || 'null'); const sharedPlacement = readSharedPlacement(); if (sharedPlacement) state.placement.result = sharedPlacement; else if (savedPlacement) state.placement.result = savedPlacement; saveSession(savedSession()); if (state.session) { try { await getMe(); } catch { saveSession(null); state.me = null; loadProgress(); } } else loadProgress(); await getPlan(); await render(); } catch (error) { app.innerHTML = `<section class="shell"><p class="error">Configuration error: ${esc(error.message)}</p><p>Set the public Supabase configuration before deploying.</p></section>`; } }
app.addEventListener('click', (event) => { handleClick(event); }); app.addEventListener('submit', (event) => { handleSubmit(event); }); window.addEventListener('hashchange', () => { render(); }); boot();
